35	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
36	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
37	
38	const BASE_PREMIUM: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	  potion: 40,
43	  rune: 25,
44	  moonstone: 25,
45	};
46	
47	const FIRST_INSURANCE_SURCHARGE = 1.1;
48	const POLICY_FEE = 5;
49	
50	const quote = (items: Item[]): QuoteResult => {
51	  const totalBasePremium = items.reduce((total, item) => total + BASE_PREMIUM[item.type], 0);
52	  return { premium: roundUpToWholeG(totalBasePremium * FIRST_INSURANCE_SURCHARGE) + POLICY_FEE };
53	};
54	
55	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
56	  const results = scenario.steps.map((step) => {
57	    if (step.op === "quote") return quote(step.items);
58	    throw new Error("claim steps are not implemented yet");
59	  });
60	  return { results };
61	};
