const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const POLICY_FEE = 5;

const quote = (items: Item[]): QuoteResult => {
  const totalBasePremium = items.reduce((total, item) => total + BASE_PREMIUM[item.type], 0);
  const withFirstInsuranceSurcharge = totalBasePremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
  return { premium: roundUpToWholeG(withFirstInsuranceSurcharge) + POLICY_FEE };
};
